/** Managed local engine and atomic workspace publication for whole novel batches. */
import { createHash } from 'node:crypto';
import { lstat, mkdir, mkdtemp, readFile, readdir, realpath, rename, rm } from 'node:fs/promises';
import { isAbsolute, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const script = fileURLToPath(new URL('../python/engine.py', import.meta.url)).replace(/\.asar([/\\])/u, '.asar.unpacked$1');
const inside = (root, value) => { const rel = relative(root, value); return rel === '' || (!isAbsolute(rel) && rel !== '..' && !rel.startsWith(`..${sep}`)); };

/** Resolve deployment limits once; protocol identities are generated by the child engine. */
export function resolveConfig(config = {}) {
  if (!config || typeof config !== 'object' || Array.isArray(config)) throw new TypeError('Invalid Fanqie configuration');
  const defaults = { pythonExecutable: '', requestTimeoutMs: 30_000, callTimeoutMs: 30 * 60_000, graceMs: 1000,
    maxBooks: 10, batchSize: 10, maxResponseBytes: 16 * 1024 ** 2, maxChapterBytes: 2 * 1024 ** 2,
    maxBookBytes: 128 * 1024 ** 2, maxOutputBytes: 16 * 1024 ** 2 };
  if (Object.keys(config).some(key => !Object.hasOwn(defaults, key))) throw new TypeError('Unknown Fanqie setting');
  const settings = { ...defaults, ...config };
  if (typeof settings.pythonExecutable !== 'string') throw new TypeError('Invalid Python executable');
  for (const key of Object.keys(defaults).filter(key => key !== 'pythonExecutable')) {
    if (!Number.isSafeInteger(settings[key]) || settings[key] <= 0) throw new TypeError(`Invalid Fanqie setting: ${key}`);
  }
  return Object.freeze(settings);
}

/** Normalize only official page links or decimal book IDs, preserving large integer strings. */
export function bookId(value) {
  if (typeof value !== 'string') throw new TypeError('Book IDs must be strings');
  if (/^\d{10,24}$/u.test(value)) return value;
  let url;
  try { url = new URL(value); } catch (error) { throw new TypeError('Use an official Fanqie book link or ID'); }
  const match = /^\/page\/(\d{10,24})\/?$/u.exec(url.pathname);
  if (url.protocol !== 'https:' || url.hostname !== 'fanqienovel.com' || url.port || url.username || url.password || !match) throw new TypeError('Use an official Fanqie book link or ID');
  return match[1];
}

async function directory(workspace, requested = 'downloads/fanqie') {
  if (!isAbsolute(workspace)) throw new TypeError('Missing session workspace');
  const root = await realpath(workspace), original = resolve(workspace, requested);
  const target = inside(workspace, original) ? resolve(root, relative(workspace, original)) : original;
  if (!inside(root, target)) throw new TypeError('Output must remain inside the session workspace');
  let current = root;
  for (const part of relative(root, target).split(sep).filter(Boolean)) {
    current = join(current, part);
    try { await mkdir(current, { mode: 0o700 }); } catch (error) { if (error.code !== 'EEXIST') throw error; }
    const info = await lstat(current);
    if (info.isSymbolicLink() || !info.isDirectory() || !inside(root, await realpath(current))) throw new TypeError('Output directory contains a link');
  }
  return target;
}

/** Each call owns its subprocess and staging tree; disposal waits for both to settle. */
export class FanqieClient {
  constructor(config, subprocess) {
    this.config = resolveConfig(config);
    this.subprocess = subprocess;
    this.lifetime = new AbortController();
    this.running = new Set();
  }

  async call(operation, args, workspace, callSignal) {
    const pending = this.run(operation, args, workspace, callSignal);
    this.running.add(pending);
    try { return await pending; } finally { this.running.delete(pending); }
  }

  async run(operation, args, workspace, callSignal) {
    let staging, handle;
    const signal = AbortSignal.any([this.lifetime.signal, AbortSignal.timeout(this.config.callTimeoutMs), ...(callSignal ? [callSignal] : [])]);
    try {
      signal.throwIfAborted();
      if (!args || typeof args !== 'object' || Array.isArray(args) || Object.keys(args).some(key => !['bookIds', ...(operation === 'download' ? ['outputDir'] : [])].includes(key))) throw new TypeError('Invalid Fanqie arguments');
      if (!Array.isArray(args.bookIds) || !args.bookIds.length || args.bookIds.length > this.config.maxBooks) throw new TypeError('Invalid number of books');
      const ids = args.bookIds.map(bookId);
      if (new Set(ids).size !== ids.length) throw new TypeError('Duplicate books');
      if (args.outputDir !== undefined && (typeof args.outputDir !== 'string' || !args.outputDir.trim() || args.outputDir.includes('\0'))) throw new TypeError('Invalid output directory');
      if (!this.config.pythonExecutable) return { ok: false, complete: false, code: 'missing_runtime', message: '需要 Muse 内置的 Python/PyCryptodome 运行时，或配置 pythonExecutable' };
      const python = await this.subprocess.resolveExecutable(this.config.pythonExecutable, undefined, signal);
      const output = operation === 'download' ? await directory(workspace, args.outputDir) : undefined;
      if (output) staging = await mkdtemp(join(output, '.fanqie-'));
      const { pythonExecutable: _python, ...settings } = this.config;
      handle = this.subprocess.spawn({ argv: [python, '-I', '-B', script], cwd: workspace,
        stdio: { stdin: { data: JSON.stringify({ operation, bookIds: ids, staging, settings }) },
          stdout: { maxBytes: this.config.maxOutputBytes }, stderr: { maxBytes: 4096 } }, signal, graceMs: this.config.graceMs });
      const outcome = await handle.done;
      await handle.waitForExit();
      signal.throwIfAborted();
      const captured = handle.collected.stdout?.readFrom(0);
      if (!captured || captured.lossy || captured.truncated || typeof captured.text !== 'string' || Buffer.byteLength(captured.text) > this.config.maxOutputBytes) throw new Error('engine_output');
      const result = JSON.parse(captured.text);
      if (!result || typeof result !== 'object' || typeof result.ok !== 'boolean') throw new Error('engine_output');
      if (outcome.signal || outcome.exitCode !== 0 || !result.ok) return { ok: false, complete: false, code: typeof result.code === 'string' && /^[a-zA-Z_]{1,64}$/u.test(result.code) ? result.code : 'engine_failed', message: '番茄下载失败；未完成文件已清理' };
      if (!Array.isArray(result.items) || result.items.length !== ids.length || result.items.some((item, index) => item.bookId !== ids[index] || !Number.isSafeInteger(item.chapterCount) || item.chapterCount < 1)) throw new Error('engine_output');
      if (operation === 'download') {
        if (!result.complete) throw new Error('incomplete_batch');
        const files = await readdir(staging);
        if (files.length !== ids.length || files.some(file => !ids.some(id => file === `${id}.txt`))) throw new Error('unexpected_output');
        for (const item of result.items) {
          if (item.file !== `${item.bookId}.txt` || item.complete !== true || item.downloadedChapters !== item.chapterCount || item.chapters?.length !== item.chapterCount) throw new Error('incomplete_batch');
          const file = join(staging, item.file), info = await lstat(file);
          if (!info.isFile() || info.isSymbolicLink() || info.size > this.config.maxBookBytes + 4096 || info.size !== item.bytes) throw new Error('invalid_file');
          if (createHash('sha256').update(await readFile(file)).digest('hex') !== item.sha256) throw new Error('file_hash');
        }
        signal.throwIfAborted();
        const final = join(output, `fanqie-${staging.split(sep).at(-1).slice(8)}`);
        await rename(staging, final);
        staging = undefined;
        return { ...result, outputDir: final, items: result.items.map(item => ({ ...item, file: join(final, item.file) })) };
      }
      return result;
    } catch (error) {
      return { ok: false, complete: false, code: signal.aborted ? 'cancelled' : error instanceof TypeError ? 'invalid_arguments' : 'engine_failed',
        message: signal.aborted ? '番茄任务已取消，未完成文件已清理' : '番茄任务失败，检查书籍 ID、下载目录或本地运行时；未完成文件已清理' };
    } finally {
      if (handle) { handle.terminate(); await Promise.allSettled([handle.done, handle.waitForExit()]); }
      if (staging) await rm(staging, { recursive: true, force: true });
    }
  }

  async dispose() {
    this.lifetime.abort();
    await Promise.allSettled([...this.running]);
  }
}
